// 📁 src/App.jsx
import { Routes, Route } from "react-router-dom";
import AdminLayout from "@/layout/AdminLayout.jsx";
import AdminLogin from "@/pages/admin/AdminLogin";
import adminRoutes from "@/routes/AdminRoutes"; // ← on importe la liste

export default function App() {
  return (
    <Routes>
      {/* Public */}
      <Route path="/admin/login" element={<AdminLogin />} />

      {/* Espace admin */}
      <Route path="/admin" element={<AdminLayout />}>
        {/* on “déplie” TOUTES les routes déclarées dans AdminRoutes.jsx */}
        {adminRoutes.map((r, i) =>
          r.index ? (
            <Route key={`admin-index-${i}`} index element={r.element} />
          ) : (
            <Route key={`admin-${r.path}-${i}`} path={r.path} element={r.element} />
          )
        )}
      </Route>

      {/* (optionnel) catch-all global */}
      <Route path="*" element={<div style={{padding:16}}>404</div>} />
    </Routes>
  );
}
