// 📁 frontend/routes/AdminRoutes.jsx
import { Navigate } from "react-router-dom";
import RolePrivateRoute from "../components/RolePrivateRoute";

import AdminReferents from "../pages/admin/AdminReferents";
import { Users, BarChart2, UserCheck } from "lucide-react";

// Pages Admin
import DashboardHome from "../pages/admin/DashboardHome";
import AdminOffres from "../pages/admin/AdminOffres";
import AdminFormOffre from "../pages/admin/AdminFormOffre";
import OffreSuccess from "../pages/admin/OffreSuccess";
import AdminCandidatures from "../pages/admin/AdminCandidatures";
import CandidatureDetail from "../pages/admin/CandidatureDetail";
import AdminCandidatureDetail from "../pages/admin/AdminCandidatureDetail";
import AdminActualites from "../pages/admin/AdminActualites";
import FormActualite from "../pages/admin/FormActualite";
import AdminServices from "../pages/admin/AdminServices";
import AdminGalerie from "../pages/admin/AdminGalerie";
import AdminMessages from "../pages/admin/AdminMessages";
import GestionAdmins from "../pages/admin/GestionAdmins";
import AdminUtilisateurs from "../pages/admin/AdminUtilisateurs";
import FormUtilisateur from "../pages/admin/FormUtilisateur";
import StatResumePage from "../pages/admin/StatResumePage";
import AdminPartenaires from "../pages/admin/AdminPartenaires"; // en haut

// Divers
import Notifications from "../pages/Notifications";
import Messages from "../pages/Messages";
import NotFound from "../pages/NotFound";

const adminRoutes = [
  // 🏠 Redirection /admin
  { index: true, element: <Navigate to="dashboard" replace /> },

  // 🧾 Tableau de bord
  {
    path: "dashboard",
    label: "Dashboard",
    icon: <BarChart2 size={18} />,
    element: (
      <RolePrivateRoute allowedRoles={["admin"]}>
        <DashboardHome />
      </RolePrivateRoute>
    ),
  },

  // 📈 Statistiques détaillées
  {
    path: "statistiques",
    label: "Statistiques",
    icon: <BarChart2 size={18} />,
    element: (
      <RolePrivateRoute allowedRoles={["admin"]}>
        <StatResumePage />
      </RolePrivateRoute>
    ),
  },

  // 📄 Offres
  { path: "offres", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminOffres /></RolePrivateRoute> },
  { path: "offres/ajouter", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminFormOffre /></RolePrivateRoute> },
  { path: "offres/modifier/:id", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminFormOffre editMode={true} /></RolePrivateRoute> },
  { path: "offres/:id/success", element: <OffreSuccess /> },

  // 🖼️ Galerie
  { path: "galerie", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminGalerie /></RolePrivateRoute> },
  { path: "referents", label: "Référents", icon: <UserCheck />, element: ( <RolePrivateRoute allowedRoles={["admin"]}> <AdminReferents /> </RolePrivateRoute> ), },

  // 👥 Candidatures
  { path: "candidatures", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminCandidatures /></RolePrivateRoute> },
  { path: "candidatures/:offreId", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminCandidatures /></RolePrivateRoute> },
  { path: "candidature/:id", element: <RolePrivateRoute allowedRoles={["admin"]}><CandidatureDetail /></RolePrivateRoute> },
  { path: "candidature/detail/:id", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminCandidatureDetail /></RolePrivateRoute> },

  // 🛠️ Services
  { path: "services", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminServices /></RolePrivateRoute> },

  // 📰 Actualités
  { path: "actualites", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminActualites /></RolePrivateRoute> },
  { path: "actualites/ajouter", element: <RolePrivateRoute allowedRoles={["admin"]}><FormActualite /></RolePrivateRoute> },
  { path: "actualites/edit/:id", element: <RolePrivateRoute allowedRoles={["admin"]}><FormActualite /></RolePrivateRoute> },

  { path: "partenaires", label: "Partenaires", icon: <Users />, element: ( <RolePrivateRoute allowedRoles={["admin"]}> <AdminPartenaires /> </RolePrivateRoute> ), },

  // 👤 Utilisateurs
  { path: "utilisateurs", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminUtilisateurs /></RolePrivateRoute> },
  { path: "utilisateurs/ajouter", element: <RolePrivateRoute allowedRoles={["admin"]}><FormUtilisateur /></RolePrivateRoute> },
  { path: "utilisateurs/edit/:id", element: <RolePrivateRoute allowedRoles={["admin"]}><FormUtilisateur /></RolePrivateRoute> },

  // 🔐 Gestion Admins
  {
    path: "gestion-admins",
    label: "Administrateurs",
    icon: <Users />,
    element: (
      <RolePrivateRoute allowedRoles={["superAdmin"]}>
        <GestionAdmins />
      </RolePrivateRoute>
    ),
    superAdmin: true,
  },

  // 💬 Messages / Notifications
  { path: "messages", element: <RolePrivateRoute allowedRoles={["admin"]}><AdminMessages /></RolePrivateRoute> },
  { path: "messages-old", element: <RolePrivateRoute allowedRoles={["admin"]}><Messages /></RolePrivateRoute> },
  { path: "notifications", element: <RolePrivateRoute allowedRoles={["admin"]}><Notifications /></RolePrivateRoute> },

  // ❌ NotFound
  { path: "*", element: <NotFound /> },
];

export default adminRoutes;
